-- Generated by scripts/build-player-guide-seed.mts from reviewed five-language team guides.
-- No notifications, fake player accounts, or edits to existing community content.
CREATE TABLE IF NOT EXISTS player_guides (
  locale text NOT NULL, key text NOT NULL, thread_id bigint NOT NULL UNIQUE REFERENCES threads(id),
  PRIMARY KEY (locale, key)
);

DO $guide$
DECLARE tid bigint; aid bigint;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM player_guides WHERE locale = 'en' AND key = 'first-board') THEN
  SELECT id INTO STRICT aid FROM members WHERE email = 'releases@outbrick.site' AND role = 'team';
  INSERT INTO threads (category_id, author_id, title, slug, language, pinned, last_poster_id)
  VALUES ((SELECT id FROM categories WHERE slug = 'help'), aid, 'Start here: playing your first board', 'player-guide-first-board-en', 'en', false, aid) RETURNING id INTO tid;
  INSERT INTO player_guides VALUES ('en', 'first-board', tid);
  INSERT INTO posts (thread_id, author_id, number, body_md, body_html) VALUES (tid, aid, 1, 'Checked 7 October 2026 · released iOS 5.0.1

A calm match-three puzzle with 2,000 boards, 167 brick-built villages and nine 3D brick friends. Swap neighbouring bricks, match three or more, and meet each board’s goals. No timer; every board plays offline.

1. Open your current level from the Journey. Read the goals and moves remaining before choosing a brick.
2. Tap a brick, then an adjacent brick, or swipe toward that neighbour. Look for a line of at least three, or a special combination.
3. Let the cascade finish, then read which goals remain. A swap that makes no match or special combination returns the bricks; it does not spend a move.
4. Use a hint if you need a suggestion. When all displayed goals are met, the board finishes and the remaining moves add to your score.

Swap neighbouring bricks to make a line of three or more. Cascades fall around obstacles and bring new bricks in. Coloured gates, sealed rooms, portals and paint channels give each board its own task.

Complete the goals shown on the board. The board finishes as soon as they are met, and leftover moves become line blasters that add to your score. Hard, Super Hard and Boss boards change the challenge along the Journey.

The board shows moves remaining; there is no clock or countdown. At the limit, five extra moves cost 300 coins, then 500, then 900 within the same attempt, or a rewarded video. Leaving or clearing resets the coin ladder.

