DO $guide$
DECLARE tid bigint; aid bigint;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM player_guides WHERE locale = 'de' AND key = 'first-board') THEN
  SELECT id INTO STRICT aid FROM members WHERE email = 'releases@outbrick.site' AND role = 'team';
  INSERT INTO threads (category_id, author_id, title, slug, language, pinned, last_poster_id)
  VALUES ((SELECT id FROM categories WHERE slug = 'help'), aid, 'Erste Schritte: dein erstes Spielbrett', 'player-guide-first-board-de', 'de', false, aid) RETURNING id INTO tid;
