DO $links$
DECLARE target record;
BEGIN
 FOR target IN SELECT g.key, t.id, t.slug FROM player_guides g JOIN threads t ON t.id = g.thread_id WHERE g.locale = 'es' LOOP
  UPDATE posts SET body_md = replace(body_md, '/community/guide-placeholder/' || target.key, '/es/community/t/' || target.id || '/' || target.slug),
   body_html = replace(body_html, '/community/guide-placeholder/' || target.key, '/es/community/t/' || target.id || '/' || target.slug)
  WHERE number = 1 AND thread_id IN (SELECT thread_id FROM player_guides WHERE locale = 'es');
 END LOOP;
END $links$;

